from pathlib import Path
from collections import deque
from decimal import Decimal, InvalidOperation

base = Path(__file__).resolve().parent
source = json.loads((base / 'prepared.json').read_text())
tasks, edges = source['tasks'], source['deps']
assert len(tasks) == len({t['id'] for t in tasks})
assert len(edges) == len({(e['project'], e['task'], e['depends_on']) for e in edges})
by_project = {}
for t in tasks:
    assert set(('id', 'project', 'name', 'duration', 'owner')).issubset(t)
    assert all(isinstance(t[k], str) and t[k] for k in ('id', 'project', 'name', 'owner'))
    try:
        d = Decimal(str(t['duration']))
        bad = not d.is_finite() or d <= 0
    except InvalidOperation:
        bad = True
    assert bad == t['bad'], t
    if not bad:
        assert d == d.to_integral_value() and int(d) == t['days']
    by_project.setdefault(t['project'], {})[t['id']] = t
assert len(by_project) == 60
edge_projects = {p: [] for p in by_project}
for e in edges:
    assert e['project'] in edge_projects
    edge_projects[e['project']].append(e)
excluded, calculated = [], []
checks = {'projects': 0, 'tasks': 0, 'edges': 0}
for p, ts in by_project.items():
    esrc = edge_projects[p]
    bad = sum(t['bad'] for t in ts.values())
    missing = sum(e['task'] not in ts or e['depends_on'] not in ts for e in esrc)
    if bad or missing:
        excluded.append(dict(project=p, reason='bad_duration' if bad else 'missing_dep', detail_count=bad or missing))
        continue
    pred = {i: [] for i in ts}
    succ = {i: [] for i in ts}
    for e in esrc:
        pred[e['task']].append(e['depends_on'])
        succ[e['depends_on']].append(e['task'])
    degree = {i: len(pred[i]) for i in ts}
    queue = deque(i for i in ts if degree[i] == 0)
    order = []
    while queue:
        i = queue.popleft()
        order.append(i)
        for j in succ[i]:
            degree[j] -= 1
            if degree[j] == 0:
                queue.append(j)
    if len(order) != len(ts):
        blocked = {i for i in ts if degree[i] > 0}
        # Independent readiness fixed point checks cycle plus downstream blockage.
        ready = set()
        while True:
            new = {i for i in ts if all(j in ready for j in pred[i])} | ready
            if new == ready:
                break
            ready = new
        assert blocked == set(ts) - ready
        excluded.append(dict(project=p, reason='cycle', detail_count=len(blocked)))
        continue
    starts, finishes, latest = {}, {}, {}
    for i in order:
        starts[i] = max((finishes[j] for j in pred[i]), default=0)
        finishes[i] = starts[i] + ts[i]['days']
    duration = max(finishes.values())
    for i in reversed(order):
        lf = min((latest[j] for j in succ[i]), default=duration)
        latest[i] = lf - ts[i]['days']
    # An independent repeated-relaxation pass checks forward/backward results.
    forward = {i: 0 for i in ts}
    backward = {i: duration - ts[i]['days'] for i in ts}
    for _ in range(len(ts)):
        changed = False
        for e in esrc:
            a, b = e['depends_on'], e['task']
            n = max(forward[b], forward[a] + ts[a]['days'])
            m = min(backward[a], backward[b] - ts[a]['days'])
            changed |= n != forward[b] or m != backward[a]
            forward[b], backward[a] = n, m
        if not changed:
            break
    assert forward == starts and backward == latest
    for e in esrc:
        assert finishes[e['depends_on']] <= starts[e['task']]
    for i in ts:
        slack = latest[i] - starts[i]
        assert slack >= 0 and all(type(v) is int for v in (starts[i], finishes[i], slack))
        calculated.append(dict(id=i, project=p, owner=ts[i]['owner'], es=starts[i], ef=finishes[i], slack=slack, critical=slack == 0))
    checks['projects'] += 1
    checks['tasks'] += len(ts)
    checks['edges'] += len(esrc)
assert len(calculated) + sum(len(by_project[e['project']]) for e in excluded) == len(tasks)
result = dict(excluded=excluded, tasks=calculated, checks=checks)
(base / 'graph.json').write_text(json.dumps(result, ensure_ascii=False), encoding='utf-8')
print(json.dumps(dict(excluded=excluded, checks=checks), ensure_ascii=False))
